def nest(flat, idx):
    out = {}
    for k, v in flat.items():
        cur = out
        parts = k.split(".")
        for p in parts[:-1]:
            cur = cur.setdefault(p, {})
            assert isinstance(cur, dict), k
        assert parts[-1] not in cur, f"duplicate {k}"
        cur[parts[-1]] = v[idx]
    return out

