    root = Path(__file__).resolve().parent.parent / "src" / "locales"
    for i, lang in enumerate(["en", "zh-TW"]):
        (root / f"{lang}.json").write_text(json.dumps(nest(S, i), ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(len(S), "keys")
